def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--release", type=Path, required=True, help="Extracted configbackup-1.2.0 directory")
    parser.add_argument("--output", type=Path, required=True, help="New local results directory")
    args = parser.parse_args()
    if sys.version_info < (3, 10):
        parser.error("Python 3.10+ is required")
    root = args.release.resolve()
    if not (root / "tests/test_snapshot_safety.py").is_file():
        parser.error("Release test files are missing; extract the entire release ZIP")
    output = args.output.resolve()
    if str(output).startswith(("\\\\", "//")):
        parser.error("Choose a local output folder")
    if os.name == "nt":
        import ctypes
        if ctypes.windll.kernel32.GetDriveTypeW(str(output.anchor)) == 4:
            parser.error("Choose a local folder, not a mapped network drive")
    try:
        output.mkdir(parents=True, exist_ok=False)
    except FileExistsError:
        parser.error("Output already exists; choose a new directory")
    scratch = output / "temporary-fixtures"
    scratch.mkdir()
    tempfile.tempdir = str(scratch)
    sys.dont_write_bytecode = True
    sys.path[:0] = [str(root), str(root / "tests")]
    # Process-local isolation from an operator's current Git repository/config.
    for name in list(os.environ):
        if name.startswith("GIT_") or name.startswith("CONFIGBACKUP_"):
            del os.environ[name]
    git_config = output / "empty-git-config"
    git_config.write_text("", encoding="utf-8")
    git_templates = scratch / "empty-git-template"
    git_templates.mkdir()
    os.environ.update(GIT_CONFIG_NOSYSTEM="1", GIT_CONFIG_GLOBAL=str(git_config),
                      GIT_TEMPLATE_DIR=str(git_templates), GIT_TERMINAL_PROMPT="0")
    payload = {"release": "1.2.0", "started_at": dt.datetime.now(dt.timezone.utc).isoformat(),
               "platform": platform.platform(), "python": sys.version,
               "test_kind": "synthetic local fixtures; no live Windows or database claim",
               "git_available": bool(shutil.which("git")), "results": []}
    log = io.StringIO()
    fatal = None
    try:
        import configbackup
        if configbackup.APP_VERSION != "1.2.0":
            raise ValueError("Expected ConfigBackup 1.2.0")
        import test_snapshot_safety
        for label, method, needs_git in CASES:
            row = {"check": label, "test": method}
            if needs_git and not payload["git_available"]:
                row.update(status="NOT RUN", reason="Git is not installed/on PATH")
            else:
                suite = unittest.defaultTestLoader.loadTestsFromName(method) if '.' in method else unittest.TestSuite([test_snapshot_safety.SafetyTests(method)])
                with contextlib.redirect_stdout(log), contextlib.redirect_stderr(log):
                    result = unittest.TextTestRunner(stream=log, verbosity=2).run(suite)
                row.update(status="PASS" if result.wasSuccessful() and not result.skipped else
                           "NOT RUN" if result.skipped else "FAIL",
                           failures=len(result.failures), errors=len(result.errors))
            payload["results"].append(row)
            print(row["status"] + ": " + label, flush=True)
    except (Exception, KeyboardInterrupt) as exc:
        fatal = str(exc) or type(exc).__name__
        payload["error"] = fatal
    payload["status"] = "FAIL" if fatal or any(row["status"] == "FAIL" for row in payload["results"]) else (
        "PASS" if len(payload["results"]) == len(CASES) and all(row["status"] == "PASS" for row in payload["results"]) else "INCOMPLETE")
    payload["finished_at"] = dt.datetime.now(dt.timezone.utc).isoformat()
    (output / "results.json").write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8")
    (output / "test-log.txt").write_text(log.getvalue(), encoding="utf-8")
    (output / "SUMMARY.txt").write_text(payload["status"] + "\n" + "\n".join(
        row["status"] + ": " + row["check"] for row in payload["results"]) +
        ("\nError: " + fatal if fatal else "") + "\nNo live platform or database capability was tested.\n", encoding="utf-8")
    print(payload["status"] + ": " + str(output / "SUMMARY.txt"))
    return {"PASS": 0, "FAIL": 1, "INCOMPLETE": 3}[payload["status"]]


if __name__ == "__main__":
    raise SystemExit(main())
